      final tool = bt.shellTool(
        MemoryExecutionEnv(cwd: '/work', shell: shell),
        retryBackoff: Duration.zero,
      );
      final result = await tool.execute({
        'command': 'aws configure set aws_access_key_id [REDACTED:AWS Access Key]',
