      // fail (the configure-git-webserver autopsy class).
      const token = '[REDACTED:AWS Access Key]';
      const command = 'aws configure set aws_access_key_id $token';
      expect(
        redactBashCommandSecretShapes(
          command,
          approvedLiterals: {token},
        ),
        isNull,
      );
    });

