+      final rewrite = redactBashCommandSecretShapes(
+        'export GH_TOKEN=ghp_${'A' * 36}',
+      )!;
+      expect(rewrite.command, 'export GH_TOKEN=[REDACTED:GitHub Token]');
+      expect(rewrite.notice, contains('GitHub Token'));
+    });
